    // 50G/100G
    guardrails().setDataDiskUsageMaxDiskSize("100GiB");
    assertThat(monitor.getDiskUsage()).isEqualTo(0.5);
    // 50G/75G
    guardrails().setDataDiskUsageMaxDiskSize("75GiB");
    assertThat(monitor.getDiskUsage()).isEqualTo(0.66667);
    // 50G/50G
