    assertThat(monitor.getDiskUsage()).isEqualTo(1.0);
    // 50G/49G
    guardrails().setDataDiskUsageMaxDiskSize("49GiB");
    assertThat(monitor.getDiskUsage()).isEqualTo(1.02041);
}

